def classify_landscape(
    cover: Mapping[str, float], terrain: Mapping[str, float]
) -> str:
    """Assign one transparent collection stratum from WorldCover plus DEM."""

    alpine_cover = cover.get("snow_ice", 0.0) + cover.get("moss_lichen", 0.0)
    if (
        alpine_cover >= 1.0
        or terrain["elevation_p90_m"] >= 3_000
        or (terrain["elevation_p90_m"] >= 2_500 and terrain["slope_p90_deg"] >= 15)
    ):
        return "alpine"
    if terrain["elevation_p90_m"] >= 1_500 or terrain["slope_p90_deg"] >= 15:
        return "mountain"
    if cover.get("built_up", 0.0) >= 12.0:
        return "urban"
    if cover.get("bare_sparse", 0.0) >= 35.0:
        return "desert_bare"
    if cover.get("tree", 0.0) >= 40.0:
        return "forest"
    if cover.get("cropland", 0.0) >= 40.0:
        return "cropland"
    water_cover = (
        cover.get("water", 0.0)
        + cover.get("wetland", 0.0)
        + cover.get("mangrove", 0.0)
    )
    if water_cover >= 25.0:
        return "water_wetland"
    if cover.get("shrubland", 0.0) + cover.get("grassland", 0.0) >= 40.0:
        return "shrub_grass"
    return "mixed"

def classify_esri_landscape(
    cover: Mapping[str, float], terrain: Mapping[str, float]
) -> str:
    """Assign a collection stratum from Esri 2025 annual land cover plus DEM."""

    if (
        cover.get("snow_ice", 0.0) >= 1.0
        or terrain["elevation_p90_m"] >= 3_000
        or (terrain["elevation_p90_m"] >= 2_500 and terrain["slope_p90_deg"] >= 15)
    ):
        return "alpine"
    if terrain["elevation_p90_m"] >= 1_500 or terrain["slope_p90_deg"] >= 15:
        return "mountain"
    if cover.get("built", 0.0) >= 12.0:
        return "urban"
    if cover.get("bare", 0.0) >= 35.0:
        return "desert_bare"
    if cover.get("trees", 0.0) >= 40.0:
        return "forest"
    if cover.get("crops", 0.0) >= 40.0:
        return "cropland"
    if cover.get("water", 0.0) + cover.get("flooded_vegetation", 0.0) >= 25.0:
        return "water_wetland"
    if cover.get("rangeland", 0.0) >= 40.0:
        return "shrub_grass"
    return "mixed"
